import { CliError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

export function parseGraph(text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop()
  }

  const declaredCost = new Map() // name -> cost (only for `task` lines)
  const deps = new Map() // name -> Set<string>
  const usedNames = [] // names used by `dep` lines, in input order

  const ensureDeps = (name) => {
    if (!deps.has(name)) deps.set(name, new Set())
    return deps.get(name)
  }

  for (let i = 0; i < rawLines.length; i++) {
    const lineNo = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'task') {
      if (tokens.length !== 3) {
        throw new CliError(2, `error: line ${lineNo}: expected task <name> <cost>`)
      }
      const name = tokens[1]
      const costStr = tokens[2]
      if (!NAME_RE.test(name)) {
        throw new CliError(2, `error: line ${lineNo}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(2, `error: line ${lineNo}: cost must be a non-negative integer`)
      }
      if (declaredCost.has(name)) {
        throw new CliError(2, `error: line ${lineNo}: task ${name} is declared twice`)
      }
      declaredCost.set(name, parseInt(costStr, 10))
      ensureDeps(name)
    } else if (directive === 'dep') {
      if (tokens.length < 3) {
        throw new CliError(2, `error: line ${lineNo}: expected dep <name> <dependency>...`)
      }
      const name = tokens[1]
      const depNames = tokens.slice(2)
      usedNames.push(name)
      const set = ensureDeps(name)
      for (const d of depNames) {
        usedNames.push(d)
        set.add(d)
      }
    } else {
      throw new CliError(2, `error: line ${lineNo}: unknown directive ${directive}`)
    }
  }

