    if (!declaredCost.has(name)) {
      throw new CliError(2, `error: unknown task ${name}`)
    }
  }

  const tasks = new Map()
  for (const [name, cost] of declaredCost) {
    tasks.set(name, { cost, deps: deps.get(name) ?? new Set() })
  }

  return { tasks }
}
"}

