/**
 * Depth-first search for a cycle, starting from each task in ascending name
 * order and walking each task's dependencies in ascending name order.
 * Throws CycleError with the first cycle found.
 */
export function detectCycle(tasks) {
  const names = [...tasks.keys()].sort()
  const visited = new Set()
  const onStack = new Set()
  const stack = []

  const visit = (name) => {
    onStack.add(name)
    stack.push(name)
    const depNames = [...tasks.get(name).deps].sort()
    for (const d of depNames) {
      if (onStack.has(d)) {
        const idx = stack.indexOf(d)
        const cyclePath = stack.slice(idx).concat(d)
        throw new CycleError(cyclePath)
      }
      if (!visited.has(d)) visit(d)
    }
    onStack.delete(name)
    stack.pop()
    visited.add(name)
  }

  for (const name of names) {
    if (!visited.has(name)) visit(name)
  }
}
"}

