{"file_path":"src/schedule.js","content":"/**
 * Wave/timing computation shared by `waves` and `explain`, and priority
 * computation used by `pack`.
 */

export function computeSchedule(tasks) {
  const names = [...tasks.keys()].sort()
  const depth = new Map()
  const start = new Map()
  const finish = new Map()

  // Names are already known to be acyclic by the time this runs, and every
  // dependency name is known to be declared, so a simple memoised recursion
  // is safe (no infinite loop, no missing lookups).
  const computeFor = (name) => {
    if (finish.has(name)) return
    const task = tasks.get(name)
    let d = 0
    let s = 0
    for (const dep of task.deps) {
      computeFor(dep)
      d = Math.max(d, depth.get(dep) + 1)
      s = Math.max(s, finish.get(dep))
    }
    depth.set(name, d)
    start.set(name, s)
    finish.set(name, s + task.cost)
  }

  for (const name of names) computeFor(name)

  let total = 0
  for (const name of names) total = Math.max(total, finish.get(name))

  return { names, depth, start, finish, total }
}

export function computePriority(tasks) {
  const names = [...tasks.keys()]
  const dependents = new Map()
  for (const name of names) dependents.set(name, [])
  for (const name of names) {
    for (const dep of tasks.get(name).deps) {
      dependents.get(dep).push(name)
    }
  }

  const priority = new Map()
  const computeFor = (name) => {
    if (priority.has(name)) return priority.get(name)
    const task = tasks.get(name)
    let best = 0
    for (const child of dependents.get(name)) {
      best = Math.max(best, computeFor(child))
    }
    const value = task.cost + best
    priority.set(name, value)
    return value
  }

  for (const name of names) computeFor(name)

  return priority
}
"}

